function findMaximums(nums) {
  const n = nums.length;
  const left = new Array(n).fill(-1);
  const right = new Array(n).fill(n);
  const stack = [];

  for (let i = 0; i < n; i++) {
    while (stack.length > 0 && nums[stack[stack.length - 1]] >= nums[i]) {
      right[stack.pop()] = i;
    }
    if (stack.length > 0) {
      left[i] = stack[stack.length - 1];
    }
    stack.push(i);
  }

  const ans = new Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    const width = right[i] - left[i] - 1;
    ans[width - 1] = Math.max(ans[width - 1], nums[i]);
  }
  for (let k = n - 2; k >= 0; k--) {
    ans[k] = Math.max(ans[k], ans[k + 1]);
  }
  return ans;
}

