function findMaximums(nums) {
  // Try every subarray, keeping its running minimum, and record the best minimum per length.
  const n = nums.length;
  const best = Array(n).fill(-1);
  for (let start = 0; start < n; start++) {
    let low = Infinity;
    for (let end = start; end < n; end++) {
      low = Math.min(low, nums[end]);
      const size = end - start + 1;
      if (low > best[size - 1]) best[size - 1] = low;
    }
  }
  return best;
}

