function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 8);
    const top = [1, 3, 10, 1000000000][pick(0, 3)];
    return [Array.from({ length: n }, () => pick(0, top))];
  }
  const n = 2000;
  const shape = pick(0, 3);
  const top = shape === 1 ? 5 : 1000000000;
  const nums = Array.from({ length: n }, () => pick(0, top));
  if (shape === 2) nums.sort((a, b) => a - b);
  if (shape === 3) nums.sort((a, b) => b - a);
  return [nums];
}
